/* Portable user data only. App/model/dictionary caches and file permissions are excluded. */
(function(root){
 const defs=[['aka-highlights','marks'],['aka-notes','notes'],['aka-vocabulary','books','entries'],['akai-image-library','books']];
 const fixed=['akai.settings.v1','aka.dictionary.settings','aka.vocabulary.lastNotebook','sheetColors','sheetColor','sheetMode','viewCount','readingDirection','sensitivity','sensitivity:red','sensitivity:green','sensitivity:blue','akai.translation.engine','akai.translation.target','akai.translation.writing','akai.translation.ocr'];
 const allowed=k=>fixed.includes(k)||k.startsWith('page:')&&k.length<2048;
 let chain=Promise.resolve();
 function exclusive(fn){if(root.navigator?.locks)return navigator.locks.request('aka-user-data-v1',fn);const p=chain.then(fn,fn);chain=p.catch(()=>{});return p}
 function db(name){return new Promise((resolve,reject)=>{const q=indexedDB.open(name,1);q.onupgradeneeded=()=>{const d=q.result;if(name==='aka-highlights')d.createObjectStore('marks',{keyPath:'id'}).createIndex('book','book');if(name==='aka-notes')d.createObjectStore('notes',{keyPath:'id'}).createIndex('book','book');if(name==='aka-vocabulary'){d.createObjectStore('books',{keyPath:'id'});const s=d.createObjectStore('entries',{keyPath:'id'});s.createIndex('notebook','notebook');s.createIndex('dedupe','dedupe',{unique:true})}if(name==='akai-image-library')d.createObjectStore('books',{keyPath:'id'});if(name==='aka-user-files')d.createObjectStore('meta')};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);q.onblocked=()=>reject(Error('다른 앱 창을 닫고 다시 시도하세요.'))})}
 async function tx(name,stores,mode,fn){const d=await db(name);try{return await new Promise((resolve,reject)=>{const t=d.transaction(stores,mode);let out;try{fn(t,v=>out=v)}catch(e){t.abort();reject(e);return}t.oncomplete=()=>resolve(out);t.onerror=t.onabort=()=>reject(t.error||Error('저장소 작업 실패'))})}finally{d.close()}}
 const metaGet=key=>tx('aka-user-files',['meta'],'readonly',(t,set)=>{const q=t.objectStore('meta').get(key);q.onsuccess=()=>set(q.result)});
 const metaPut=(key,value)=>tx('aka-user-files',['meta'],'readwrite',t=>t.objectStore('meta').put(value,key));
 async function readDb(name,stores){return tx(name,stores,'readonly',(t,set)=>{const out={};set(out);for(const s of stores){const q=t.objectStore(s).getAll();q.onsuccess=()=>out[s]=q.result}})}
 function preferences(){const p={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(allowed(k))p[k]=localStorage.getItem(k)}return p}
 async function snapshot(){const a=await Promise.all(defs.map(([n,...s])=>readDb(n,s)));return {marks:a[0].marks,notes:a[1].notes,notebooks:a[2].books,entries:a[2].entries,imageBooks:a[3].books,preferences:preferences()}}
 function canonical(v){if(Array.isArray(v))return '['+v.map(canonical).join(',')+']';if(v&&typeof v==='object')return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical(v[k])).join(',')+'}';return JSON.stringify(v)}
 async function hash(v){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(typeof v==='string'?v:canonical(v)));return Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('')}
 function sane(v,depth=0){if(depth>25)throw Error('백업 구조가 너무 복잡합니다.');if(typeof v==='string'&&v.length>200000)throw Error('백업 문자열이 너무 깁니다.');if(typeof v==='number'&&!Number.isFinite(v))throw Error('잘못된 숫자입니다.');if(v&&typeof v==='object'){if(Array.isArray(v)&&v.length>100000)throw Error('백업 항목이 너무 많습니다.');for(const k of Object.keys(v)){if(['__proto__','constructor','prototype'].includes(k))throw Error('허용되지 않는 백업 속성입니다.');sane(v[k],depth+1)}}}
 const id=v=>typeof v==='string'&&v.length>0&&v.length<2048;
 function validate(p){if(!p||typeof p!=='object')throw Error('사용자 데이터가 없습니다.');sane(p);for(const k of ['marks','notes','notebooks','entries','imageBooks']){if(!Array.isArray(p[k])||p[k].length>100000)throw Error('백업 목록 오류');const ids=new Set();for(const r of p[k]){if(!id(r?.id)||ids.has(r.id))throw Error('중복되거나 잘못된 ID입니다.');ids.add(r.id)}}
  for(const r of p.marks)if(!id(r.book)||!HighlightStore.valid(r))throw Error('형광펜 정보 오류');
  for(const r of p.notes)if(!id(r.book)||!NoteStore.valid(r))throw Error('메모 정보 오류');
  for(const r of p.notebooks)if(!VocabularyStore.validBook(r))throw Error('단어장 정보 오류');
  const books=new Set(p.notebooks.map(r=>r.id));for(const r of p.entries)if(!VocabularyStore.valid(r)||!books.has(r.notebook))throw Error('단어 또는 소속 단어장 정보 오류');
  for(const r of p.imageBooks)if(r.schema!==1||!['zip','folder','image'].includes(r.kind)||typeof r.title!=='string'||!Array.isArray(r.pages)||r.pages.length>10000||!r.pages.every(a=>id(a.id)&&typeof a.path==='string'&&Number.isFinite(a.bytes)&&a.bytes>=0&&typeof a.sha256==='string')||r.position&&(!id(r.position.pageId)||!r.pages.some(a=>a.id===r.position.pageId)))throw Error('이미지 책 기록 오류');
  if(!p.preferences||Array.isArray(p.preferences)||typeof p.preferences!=='object')throw Error('설정 정보 오류');
  for(const [k,v]of Object.entries(p.preferences)){if(!allowed(k)||typeof v!=='string'||v.length>200000)throw Error('허용되지 않는 설정입니다.');if(k.startsWith('page:')&&(!/^\d+$/.test(v)||+v<1))throw Error('읽기 위치 오류');if(['akai.settings.v1','aka.dictionary.settings','sheetColors'].includes(k))JSON.parse(v)}return p}
 async function encode(p){validate(p);p=JSON.parse(JSON.stringify(p));validate(p);const text=JSON.stringify({format:'aka-sheet-user-data',schema:1,appVersion:typeof APP_RELEASE==='undefined'?'':APP_RELEASE.version,createdAt:new Date().toISOString(),checksum:await hash(p),data:p},null,2);if(new TextEncoder().encode(text).length>100*1024*1024)throw Error('백업은 100MB 이하만 지원합니다.');return text}
 async function decode(text){if(new TextEncoder().encode(text).length>100*1024*1024)throw Error('백업은 100MB 이하만 지원합니다.');const v=JSON.parse(text);if(v.format!=='aka-sheet-user-data'||v.schema!==1)throw Error('지원하지 않는 백업 형식 또는 버전입니다.');validate(v.data);if(v.checksum!==await hash(v.data))throw Error('백업 검증 실패: 파일이 손상되었을 수 있습니다.');return v}
 function summary(p){return {marks:p.marks.length,text:p.notes.filter(r=>r.type!=='drawing').length,drawing:p.notes.filter(r=>r.type==='drawing').length,books:p.notebooks.length,words:p.entries.length,positions:new Set([...Object.keys(p.preferences).filter(k=>k.startsWith('page:')).map(k=>k.slice(5)),...p.imageBooks.filter(r=>r.position).map(r=>r.id)]).size,settings:!!p.preferences['akai.settings.v1']}}
 function plan(current,incoming,applyPrefs){const out={marks:[],notes:[],notebooks:[],entries:[],imageBooks:[],preferences:applyPrefs?Object.fromEntries(Object.entries(incoming.preferences).filter(([k])=>!Object.hasOwn(current.preferences,k))):{}};
  for(const k of ['marks','notes']){const key=r=>canonical({...r,id:''}),seen=new Set(current[k].map(key)),ids=new Set(current[k].map(r=>r.id));for(const record of incoming[k]){const r=structuredClone(record);if(seen.has(key(r)))continue;if(ids.has(r.id))r.id=crypto.randomUUID();ids.add(r.id);seen.add(key(r));out[k].push(r)}}
  const map=new Map(),bs=new Map(current.notebooks.map(r=>[r.id,r]));for(const record of incoming.notebooks){const r=structuredClone(record),old=bs.get(r.id),same=old&&old.name===r.name&&old.icon===r.icon?old:[...bs.values()].find(b=>b.restoredFromId===r.id&&b.name===r.name&&b.icon===r.icon);if(same){map.set(r.id,same.id);continue}const original=r.id;if(old){r.id=crypto.randomUUID();r.restoredFromId=original}map.set(original,r.id);bs.set(r.id,r);out.notebooks.push(r)}
  const ids=new Set(current.entries.map(r=>r.id)),dedupes=new Set(current.entries.map(VocabularyStore.dedupe));for(const record of incoming.entries){const r=structuredClone(record);r.notebook=map.get(r.notebook);r.dedupe=VocabularyStore.dedupe(r);if(dedupes.has(r.dedupe))continue;if(ids.has(r.id))r.id=crypto.randomUUID();delete r.expectedUpdatedAt;ids.add(r.id);dedupes.add(r.dedupe);out.entries.push(r)}
  const images=new Map(current.imageBooks.map(r=>[r.id,r]));for(const record of incoming.imageBooks){const r=structuredClone(record),old=images.get(r.id);if(!old)out.imageBooks.push(r);else if(applyPrefs&&!old.position&&r.position)out.imageBooks.push({...old,position:r.position})}return out}
 const groups=p=>[['aka-highlights',{marks:p.marks}],['aka-notes',{notes:p.notes}],['aka-vocabulary',{books:p.notebooks,entries:p.entries}],['akai-image-library',{books:p.imageBooks}]];
 async function merge(incoming,applyPrefs){return exclusive(async()=>{validate(incoming);const before=await snapshot(),p=plan(before,incoming,applyPrefs),done=[];await metaPut('beforeRestore',before);
  try{for(const [name,stores]of groups(p)){await tx(name,Object.keys(stores),'readwrite',t=>{for(const [s,items]of Object.entries(stores))for(const r of items)name==='akai-image-library'?t.objectStore(s).put(r):t.objectStore(s).add(r)});done.push([name,stores])}for(const [k,v]of Object.entries(p.preferences))localStorage.setItem(k,v);return p}
  catch(error){try{for(const [name,stores]of done.reverse())await tx(name,Object.keys(stores),'readwrite',t=>{for(const [s,items]of Object.entries(stores))for(const r of items){const old=name==='akai-image-library'?before.imageBooks.find(b=>b.id===r.id):null;if(old)t.objectStore(s).put(old);else t.objectStore(s).delete(r.id)}});for(const k of Object.keys(p.preferences)){if(Object.hasOwn(before.preferences,k))localStorage.setItem(k,before.preferences[k]);else localStorage.removeItem(k)}}catch{throw Error('복원이 중단되었습니다. 기존 주석은 유지되며 일부 추가 항목이 남을 수 있습니다. 다시 열어 확인하세요.')}throw error}})}
 root.UserDataCore={exclusive,snapshot,hash,canonical,encode,decode,validate,summary,plan,merge,metaGet,metaPut};
})(globalThis);
